//! Audit PoC / property tests for GnB-SMH and `difficulty` (PoW reviewer).
//!
//! Expected outcome: every test PASSES. Tests whose name starts with
//! `finding_` pass because they *demonstrate* a documented deviation.
//!
//! Run: cargo test --release --locked -p gnb-smh --test audit_poc_pow -- --nocapture

use gnb_smh::difficulty::*;
use gnb_smh::{hash_with, Scratchpad};

// ── Cross-implementation: extra vectors generated by the normative Python
//    reference (scratchpad/agent_pow/pow_checks.py + lcg_vectors.py). ──────────

const FIXED: &[(&str, u64, &str)] = &[
    // (header recipe, nonce, Python out_hex) at log2_n = 10
    ("ff*300", 0, "01395b09a289729f848edcbdec1336bb07e1de6eeafa0c649bae12bc878a7850"),
    ("range256*2", 1 << 63, "09cf3a6f67de0ff9d2214e2b44f8a7334e38a76bcffcc0abaf39f0966e5745e4"),
    ("x", u64::MAX - 1, "a769546c076256a1b0c7c3fb10e5dde59e6063ee5d8d124ed83d3f4c9baac60d"),
    ("zeros8244", 7, "ba72314ce0fc97693da20c8b33978a9d6277466e031a9124bfd4c3c757a4dfef"),
];

fn fixed_header(recipe: &str) -> Vec<u8> {
    match recipe {
        "ff*300" => vec![0xFF; 300],
        "range256*2" => (0..512u32).map(|i| (i % 256) as u8).collect(),
        "x" => b"x".to_vec(),
        "zeros8244" => vec![0u8; 4 + 4 + 256 * 32 + 32 + 8 + 4],
        _ => unreachable!(),
    }
}

const LCG: &[(u32, usize, u64, &str)] = &[
    (10, 155, 14310528980563901811, "c3157329caea052146ea2a2340d89b6f090a1ec4b059080abfc3a6ec3f714bff"),
    (12, 58, 16451485755647954191, "5960b3ea219987f5bc909d88822737ba6ccc9315d9eb9991ecfb175d162d9791"),
    (10, 218, 6302663413203525003, "cacb796d9859fc8f28f8f3854773680890ec3a71a8c5a6f2b7f5cb09ebca5538"),
    (12, 486, 5637801486340755571, "ee8ab6849d9a751255ec0cc58c3b7a670bb410430af8f1bf6c7923401a71b788"),
    (10, 262, 17839152791468604795, "32d06f5c0412ea97bb3d4072140c0c8bb6b702ed752423ec802ec386639c1199"),
    (12, 234, 481023385720020807, "b877a65a7f35d5b3268015012ae5c80e4ec5b05183d6d1733fd4252c31c39390"),
    (10, 358, 16325499207238407983, "d8655124f3e59a9a59d2164b3bfd35f235188fe1314478460ff80df911a15761"),
    (12, 386, 458932536644923219, "a3a0f36d3c5fc8bd81199ee7b4d33e9d2b23e9da19c28b1093cbc083dccf0a58"),
];

#[test]
fn extra_vectors_match_python_reference() {
    for (recipe, nonce, want) in FIXED {
        let mut sp = Scratchpad::new(10);
        assert_eq!(hex::encode(hash_with(&mut sp, &fixed_header(recipe), *nonce)), *want, "{recipe}");
    }
    let mut x: u64 = 0x6A09_E667_F3BC_C908;
    let mut nxt = || {
        x = x.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        x
    };
    for (log2_n, len, nonce, want) in LCG {
        let ln = (nxt() % 700) as usize;
        let h: Vec<u8> = (0..ln).map(|_| (nxt() >> 56) as u8).collect();
        let n = nxt();
        assert_eq!((ln, n), (*len, *nonce));
        let mut sp = Scratchpad::new(*log2_n);
        assert_eq!(hex::encode(hash_with(&mut sp, &h, n)), *want);
    }
}

// ── Compact encoding ────────────────────────────────────────────────────────

/// No compact encoding decodes above the pow limit 0x2100ffff: the limit is the
/// largest decodable target, so `validate_pow`'s missing `target <= pow_limit`
/// check (Bitcoin's CheckProofOfWork has one) is unreachable today.
#[test]
fn max_decodable_target_is_the_pow_limit() {
    let limit = bits_to_target(0x2100_FFFF);
    let mut max = Target::ZERO;
    for exp in 32u32..=40 {
        for mant in 1u32..=0x7F_FFFF {
            if let Ok(t) = try_bits_to_target((exp << 24) | mant) {
                if t > max {
                    max = t;
                }
            }
        }
    }
    assert_eq!(max, limit);
}

/// Decode accepts non-canonical encodings (same target, different bits).
/// Consensus is safe only because accept_block compares `bits` to the
/// canonical `expected_bits` by u32 equality.
#[test]
fn finding_noncanonical_bits_decode_to_same_target() {
    let a = try_bits_to_target(0x0400_0080).unwrap();
    let b = try_bits_to_target(0x0300_8000).unwrap();
    assert_eq!(a, b);
    assert_eq!(target_to_bits(&a), 0x0300_8000);
    // also: low bytes silently dropped for exponent < 3
    assert_eq!(try_bits_to_target(0x0212_3456).unwrap(), try_bits_to_target(0x0212_3400).unwrap());
}

/// encode(decode(bits)) is canonical and stable over the whole valid space
/// (sampled: every exponent, every 97th mantissa).
#[test]
fn compact_round_trip_sweep() {
    let mut n = 0u64;
    for exp in 0u32..=255 {
        let mut mant = 1u32;
        while mant <= 0x7F_FFFF {
            let bits = (exp << 24) | mant;
            if let Ok(t) = try_bits_to_target(bits) {
                let c = target_to_bits(&t);
                assert_eq!(try_bits_to_target(c), Ok(t), "bits {bits:#x} canon {c:#x}");
                assert_eq!(target_to_bits(&bits_to_target(c)), c);
                n += 1;
            }
            mant += 97;
        }
    }
    assert!(n > 2_000_000);
}

// ── ASERT ────────────────────────────────────────────────────────────────────

fn chain_params() -> (AsertParams, AsertAnchor) {
    (
        AsertParams { target_spacing: 30, halflife: 7_200, pow_limit: bits_to_target(0x2100_FFFF) },
        AsertAnchor { height: 0, bits: 0x1F0E_9036, timestamp: 1_791_429_092 },
    )
}

/// Monotone in parent time across many integer-shift boundaries, never above
/// the limit, never zero, for several heights.
#[test]
fn asert_monotone_and_clamped_over_wide_range() {
    let (p, a) = chain_params();
    for h in [1u64, 2, 17_000, 1_000_000] {
        let base = a.timestamp + 30 * (h as i64 - 1);
        let mut prev = Target::ZERO;
        let mut dt = -3_000_000i64;
        while dt <= 3_000_000 {
            let t = asert_next_target(&p, &a, base + dt, h).unwrap();
            assert!(t >= prev, "h={h} dt={dt}");
            assert!(t <= p.pow_limit && !t.is_zero());
            prev = t;
            dt += 61;
        }
    }
}

/// A future-dated parent (MAX_FUTURE_SECS = 600) eases the next target by at
/// most 2^(600/7200) ~ 5.9 %, plus one compact rounding step.
#[test]
fn asert_future_drift_easing_is_bounded() {
    let (p, a) = chain_params();
    let mut worst = 0f64;
    for dt in (-200_000i64..200_000).step_by(997) {
        let t0 = asert_next_target(&p, &a, a.timestamp + dt, 1).unwrap();
        let t1 = asert_next_target(&p, &a, a.timestamp + dt + 600, 1).unwrap();
        if t1 == p.pow_limit {
            continue;
        }
        let f = |t: &Target| t.0.iter().fold(0f64, |acc, &b| acc * 256.0 + b as f64);
        worst = worst.max(f(&t1) / f(&t0));
    }
    assert!(worst < 1.0596, "worst easing {worst}");
}

/// FINDING (POW-free-blocks root cause): with POW_LIMIT ~ 2^256 and an absolute
/// schedule, any block whose parent set is >= ~24.3 h behind schedule gets the
/// pow limit, i.e. a per-nonce success probability of 65535/65536.
#[test]
fn finding_asert_reaches_trivial_target_after_24h_behind_schedule() {
    let (p, a) = chain_params();
    let t = asert_next_target(&p, &a, a.timestamp + 87_377, 1).unwrap();
    assert_eq!(t, p.pow_limit);
    assert_eq!(target_to_bits(&t), 0x2100_FFFF);
    assert_eq!(work(&t), 1);
    // one second less is not yet at the limit
    assert!(asert_next_target(&p, &a, a.timestamp + 87_376, 1).unwrap() < p.pow_limit);
    // a fork whose parents are 1000 blocks (8.3 h) behind gets ~18x easier
    let on = asert_next_target(&p, &a, a.timestamp, 1).unwrap();
    let off = asert_next_target(&p, &a, a.timestamp + 30_000, 1).unwrap();
    assert!(work(&on) / work(&off) >= 17);
}

/// FINDING (Info): `work()` is not the spec's floor(2^256/target) that the
/// Python "normative" file defines; it ignores the low 128 bits of the target.
#[test]
fn finding_work_differs_from_python_spec() {
    let mut t = [0u8; 32];
    t[0] = 0x80; // target = 2^255, spec work = 2^256 / 2^255 = 2
    assert_eq!(work(&Target(t)), 1);
    // target 2^127 (< 2^128): spec 2^129, Rust saturates to u128::MAX
    let mut s = [0u8; 32];
    s[16] = 0x80;
    assert_eq!(work(&Target(s)), u128::MAX);
}

/// Extreme inputs never panic and fail closed or clamp.
#[test]
fn asert_extremes_do_not_panic() {
    let (p, a) = chain_params();
    for pt in [i64::MIN, -1, 0, i64::MAX] {
        for h in [1u64, 2, u64::MAX / 2, u64::MAX] {
            let _ = asert_next_bits(&p, &a, pt, h);
        }
    }
    let big = AsertParams { target_spacing: i64::MAX, ..p };
    assert_eq!(asert_next_bits(&big, &a, i64::MIN, u64::MAX), Err(AsertError::ArithmeticOverflow));
}

/// One canonical verification: allocates the 64 MiB thread-local scratchpad
/// once per thread; report the per-evaluation wall time on this host.
#[test]
fn verification_cost_report() {
    let t = bits_to_target(0x1D00_FFFF);
    let _ = gnb_smh::verify(b"warm", 0, &t);
    let t0 = std::time::Instant::now();
    for n in 0..3u64 {
        assert!(!gnb_smh::verify(b"audit", n, &t));
    }
    let per = t0.elapsed().as_secs_f64() / 3.0;
    eprintln!("GnB-SMH canonical evaluation: {:.1} ms", per * 1e3);
}
